import { useDataQuery } from '@dhis2/app-runtime'
import useFetchAnalytics from '../../features/analytics/api/analyticsAPI'
import useFetchOrgUnits from '../../features/org-units/api/organisationAPI'
import useFetchDatasets from './datasetsAPI'

// Tests generated by GPT, not verified

// Mock DHIS2 runtime
jest.mock('@dhis2/app-runtime', () => ({
    useDataQuery: jest.fn(),
}))

describe('API hooks with mock data', () => {
    beforeEach(() => {
        jest.clearAllMocks()
    })

    test('useFetchAnalytics returns correct mocked analytics data', () => {
        const mockAnalyticsData = {
            data: {
                headers: ['event', 'value'],
                rows: [
                    ['evt123', '45'],
                    ['evt124', '32']
                ],
            },
        }
        useDataQuery.mockReturnValue(mockAnalyticsData)

        const result = useFetchAnalytics(
            'UxK2o06ScIe',
            { startDate: '2024-01-01', endDate: '2024-12-31' },
            [{ itemid: 'de123', operator: 'GT', filter: '10' }],
            ['ou123']
        )

        expect(result.data.headers).toContain('event')
        expect(result.data.rows).toHaveLength(2)
        expect(result.data.rows[0][1]).toBe('45')
    })

    test('useFetchAnalytics handles API error', () => {
        const mockError = new Error('Failed to fetch analytics data')
        const mockErrorResponse = { error: mockError }
        useDataQuery.mockReturnValue(mockErrorResponse)

        const result = useFetchAnalytics(
            'UxK2o06ScIe',
            { startDate: '2024-01-01', endDate: '2024-12-31' },
            [{ itemid: 'de123', operator: 'GT', filter: '10' }],
            ['ou123']
        )

        expect(result.error).toBe(mockError)
        expect(result.data).toBeUndefined()
    })

    test('useFetchOrgUnits returns correct mocked org unit data', () => {
        const mockOrgData = {
            data: {
                organisationUnits: [
                    {
                        id: 'ou123',
                        name: 'School A',
                        level: 3,
                        parent: { id: 'ouParent1', name: 'District 1' },
                    },
                    {
                        id: 'ou456',
                        name: 'School B',
                        level: 3,
                        parent: { id: 'ouParent1', name: 'District 1' },
                    },
                ],
            },
        }
        useDataQuery.mockReturnValue(mockOrgData)

        const result = useFetchOrgUnits(['ou123', 'ou456'])
        expect(result.data.organisationUnits[0].name).toBe('School A')
        expect(result.data.organisationUnits[1].id).toBe('ou456')
    })

    test('useFetchOrgUnits handles API error', () => {
        const mockError = new Error('Failed to fetch organization units')
        const mockErrorResponse = { error: mockError }
        useDataQuery.mockReturnValue(mockErrorResponse)

        const result = useFetchOrgUnits(['ou123', 'ou456'])

        expect(result.error).toBe(mockError)
        expect(result.data).toBeUndefined()
    })

    test('useFetchDatasets returns correct mocked dataset list', () => {
        const mockDatasetData = {
            data: {
                dataSets: [
                    { id: 'ds1', name: 'EMIS - Primary Tool' },
                    { id: 'ds2', name: 'Health Survey 2024' },
                ],
            },
        }
        useDataQuery.mockReturnValue(mockDatasetData)

        const result = useFetchDatasets()
        expect(result.data.dataSets).toHaveLength(2)
        expect(result.data.dataSets[0].name).toBe('EMIS - Primary Tool')
    })

    test('useFetchDatasets handles API error', () => {
        const mockError = new Error('Failed to fetch datasets')
        const mockErrorResponse = { error: mockError }
        useDataQuery.mockReturnValue(mockErrorResponse)

        const result = useFetchDatasets()

        expect(result.error).toBe(mockError)
        expect(result.data).toBeUndefined()
    })
})